function ApplyVersusImpulse(Vector Impulse)
{
    local vector PreVelocity;
    local vector PriorHorizontal;
    local vector PushHorizontal;
    local vector ResultVelocity;
    local float MaxHorizontal;
    local float MaxPrior;

    if (Role != ROLE_Authority || bVersusDead)
        return;

    // AirSpeed is the stock airborne speed limit (400 for Harry); JumpZ is
    // the stock jump launch (245). Keep those as the physical bounds instead
    // of accumulating the old 300..900 Flipendo push with every hit.
    PreVelocity = Velocity;
    MaxHorizontal = FMax(1.0, AirSpeed);
    MaxPrior = FMin(MaxHorizontal, FMax(0.0, GroundSpeed));
    PriorHorizontal = PreVelocity;
    PriorHorizontal.Z = 0.0;
    if (VSize2D(PriorHorizontal) > MaxPrior)
        PriorHorizontal = Normal(PriorHorizontal) * MaxPrior;
    PushHorizontal = Impulse;
    PushHorizontal.Z = 0.0;
    if (VSize2D(PushHorizontal) > MaxHorizontal)
        PushHorizontal = Normal(PushHorizontal) * MaxHorizontal;
    ResultVelocity = PushHorizontal + PriorHorizontal * 0.25;
    if (VSize2D(ResultVelocity) > MaxHorizontal)
        ResultVelocity = Normal(ResultVelocity) * MaxHorizontal;
    // A second airborne hit may refresh the bounce but never adds height.
    ResultVelocity.Z = FClamp(FMax(PreVelocity.Z, Impulse.Z),
        -JumpZ, JumpZ);
    Velocity = ResultVelocity;
    SetPhysics(PHYS_Falling);
    VersusKnockbackTraceUntil = Level.TimeSeconds + 1.0;
    NextVersusKnockbackTraceTime = 0.0;
    ClientSetVersusKnockbackVelocity(ResultVelocity);
    Log("HPVersusKnockback phase=ServerHit pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot) $ " Role=" $ string(Role)
        $ " RemoteRole=" $ string(RemoteRole)
        $ " time=" $ string(Level.TimeSeconds)
        $ " moveStamp=" $ string(CurrentTimeStamp)
        $ " loc=" $ string(Location)
        $ " preVelocity=" $ string(PreVelocity)
        $ " impulse=" $ string(Impulse)
        $ " resultVelocity=" $ string(ResultVelocity)
        $ " limitXY=" $ string(MaxHorizontal)
        $ " limitZ=" $ string(JumpZ)
        $ " physics=" $ string(Physics)
        $ " state=" $ string(GetStateName())
        $ " rotation=" $ string(Rotation));
}

function ClientSetVersusKnockbackVelocity(Vector NewVelocity)
{
    Log("HPVersusKnockback phase=OwnerBeforeRPC pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot) $ " Role=" $ string(Role)
        $ " RemoteRole=" $ string(RemoteRole)
        $ " time=" $ string(Level.TimeSeconds)
        $ " moveStamp=" $ string(CurrentTimeStamp)
        $ " loc=" $ string(Location)
        $ " velocity=" $ string(Velocity)
        $ " authoritativeVelocity=" $ string(NewVelocity)
        $ " physics=" $ string(Physics)
        $ " state=" $ string(GetStateName())
        $ " rotation=" $ string(Rotation));
    Velocity = NewVelocity;
    SetPhysics(PHYS_Falling);
    VersusKnockbackTraceUntil = Level.TimeSeconds + 1.0;
    NextVersusKnockbackTraceTime = 0.0;
    LogVersusKnockbackState("OwnerAfterRPC");
}

function LogVersusKnockbackState(string Phase)
{
    if (Level.TimeSeconds > VersusKnockbackTraceUntil
        || Level.TimeSeconds < NextVersusKnockbackTraceTime)
        return;
    Log("HPVersusKnockback phase=" $ Phase
        $ " pawn=" $ string(self) $ " slot=" $ string(VersusSlot)
        $ " Role=" $ string(Role) $ " RemoteRole=" $ string(RemoteRole)
        $ " time=" $ string(Level.TimeSeconds)
        $ " moveStamp=" $ string(CurrentTimeStamp)
        $ " loc=" $ string(Location)
        $ " velocity=" $ string(Velocity)
        $ " acceleration=" $ string(Acceleration)
        $ " physics=" $ string(Physics)
        $ " state=" $ string(GetStateName())
        $ " rotation=" $ string(Rotation));
    NextVersusKnockbackTraceTime = Level.TimeSeconds + 0.15;
}

