// M212 executes harry.PlayerWalking.PlayerTick on a subclass instance but
// resolves its state-local ProcessFalling on that instance's state. Provide
// the same stock falling bookkeeping here so the inherited tick can always
// find it; do not bypass falling, landing, sounds or Spongify.
state PlayerWalking
{
    function ProcessFalling(float DeltaTime)
    {
        local float LastTimeInAir;

        if (Physics == PHYS_Falling)
        {
            if (eLastPhysState != PHYS_Falling)
            {
                fFallingZ = Location.Z;
                fHighestZ = Location.Z;
            }
            else if (fHighestZ < Location.Z)
                fHighestZ = Location.Z;

            LastTimeInAir = fTimeInAir;
            fTimeInAir += DeltaTime;
            if (!bPlayedFallSound && fTimeInAir > 1.5)
            {
                bPlayedFallSound = True;
                if (AnimFalling != SpongifyFallAnim)
                    PlayFallDeepEmoteSound();
            }
            if (LastTimeInAir <= 0.35 && fTimeInAir > 0.35)
                PlayInAir();
        }
        else
        {
            bPlayedFallSound = False;
            fTimeInAir = 0.0;
        }
        eLastPhysState = Physics;
    }
}

